import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'pdf', 'docx', 'xlsx', 'pptx', 'odt'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def get_output_path(input_filename, fmt):
    base = os.path.splitext(input_filename)[0]
    return os.path.join(UPLOAD_DIR, f"{base}.{fmt}")

def validate_format(fmt):
    # Only allow specific output formats
    return fmt in ('pdf', 'html', 'txt', 'csv', 'png')

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    output_format = request.form.get('format', 'pdf')
    extra_args = request.form.get('args', '')

    if not file.filename:
        return jsonify({"error": "Empty filename"}), 400

    filename = secure_filename(file.filename)
    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''

    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({"error": f"Unsupported input format: {ext}"}), 400

    if not validate_format(output_format):
        return jsonify({"error": f"Unsupported output format: {output_format}"}), 400

    # Save uploaded file
    job_id = hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{filename}")
    file.save(input_path)

    output_path = get_output_path(f"{job_id}_{filename}", output_format)

    # Build conversion command using LibreOffice
    # extra_args allows passing additional LibreOffice macro parameters
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR}"
    if extra_args:
        cmd += f" {extra_args}"
    cmd += f" {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=60,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "details": result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find the output file
        expected_output = os.path.join(UPLOAD_DIR, f"{job_id}_{os.path.splitext(filename)[0]}.{output_format}")
        if os.path.exists(expected_output):
            return send_file(expected_output, as_attachment=True)
        else:
            return jsonify({"error": "Output file not found"}), 500

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple files. Accepts JSON with base64-encoded files."""
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({"error": "No files in request"}), 400
    results = []
    for item in data['files'][:10]:  # Max 10 files
        results.append({"name": item.get('name', 'unknown'), "status": "queued"})
    return jsonify({"batch_id": hashlib.md5(str(time.time()).encode()).hexdigest()[:8], "results": results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
